import React from "react";

import { AppContext, setActivePage } from "../context";
import { AppNavLink } from "./AppNavigator";

export const DashboardLinks = () => {
    const { state, dispatch } = React.useContext(AppContext);

    return (
        <div className="ss-app-config-links">
            <AppNavLink
                link={process.env.REACT_APP_LOGOUT_URL as string}
                label="Dashboard"
                icon="dashboard"
                id="Dashboard"
                isActive={state.activePage === "Dashboard"}
                onClick={() => dispatch(setActivePage("Dashboard" === state.activePage ? "" : "Dashboard"))}
            />
            {state.dashboardLinks.map((link) => (
                <AppNavLink
                    label={link.Link.Text || link.Link.Name}
                    icon={link.Link.Icon}
                    id={link.Link.Name}
                    isGrid={true}
                    isActive={state.activePage === "Dashboard"}
                    onClick={() => dispatch(setActivePage(link.Link.Name === state.activePage ? "" : link.Link.Name))}
                />
            ))}
        </div>
    );
};
